package behavioral.template.sample;

import behavioral.template.sample.processors.*;

public class Main {

    public static void main(String[] args) {
        DataProcessor csv = new CSVProcessor();
        csv.process();
        System.out.println();
        DataProcessor json = new JSONProcessor();
        json.process();
    }
}

package behavioral.template.sample.processors;

public class CSVProcessor extends DataProcessor {
    @Override
    void parseData() {
        System.out.println("Parsing CSV data");
    }

    @Override
    boolean shouldValidate() {
        return false;
    }
}

package behavioral.template.sample.processors;

public abstract class DataProcessor {

    public final void process() {
        readData();
        parseData();
        if(shouldValidate()) {
            validateData();
        }
        else {
            System.out.println("Skipping validation");
        }
        saveData();
    }

    void readData() {
        System.out.println("Reading data");
    }

    abstract void parseData();

    // Can override if required
    boolean shouldValidate() {
        return true;
    }

    void validateData() {
        System.out.println("Validating data");
    }

    void saveData() {
        System.out.println("Saving data");
    }
}

package behavioral.template.sample.processors;

public class ExcelProcessor extends DataProcessor {
    @Override
    void parseData() {
        System.out.println("Parsing Excel data");
    }
}

package behavioral.template.sample.processors;

public class JSONProcessor extends DataProcessor {
    @Override
    void parseData() {
        System.out.println("Parsing JSON data");
    }
}

